-- Q1 || IoT  || E* -> M -> A 
---  Lists all sensors that can generate observations of a given type τ that can cover the locations specied in L.

SELECT distinct s1.device_id
FROM measurements AS s1
WHERE s1.controlled_property = 'dripper'
AND ST_Within(
	s1.location,
	    (SELECT st_geomfromtext(location)
     FROM cypher('watering_adf_graph', $$
         MATCH (n:AgriFarm)
         WHERE n.name = 'ZESPRI AZ. AGR. DALLE FABBRICHE ANDREA'
         RETURN n.location
     $$) AS (location text))	
);

-- Q2 || IoT || A -> M ---
--- Selects observations generated by sensors of given type τ in the time range [tbtb; tete] that satisfy the condition cond.

SELECT *
FROM measurements
WHERE device_id LIKE '%Device%'
AND controlled_property = 'temperature'
AND timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603);

-- Q3 || IoT M -> A ---
--- Retrieves statistics (e.g., average) based on functions specifed in F during the time range [tbtb; tete].

SELECT device_id, AVG(value) FROM measurements 
WHERE controlledProperty = 'dripper'
AND timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
GROUP BY device_id;

-- Q4 || IoT || M -> E ---
--- Retrieves the names of devices who went from location lblb to location lele during the time interval [tbtb; tete]

WITH devices_near_A AS (
    SELECT device_id
    FROM measurements
    WHERE timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
      AND ST_DWithin(location, ST_MakePoint(-3.481482078, 40.31344191)::geography, 10)
    GROUP BY device_id
),
devices_near_B AS (
    SELECT device_id
    FROM measurements
    WHERE timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
      AND ST_DWithin(location, ST_MakePoint(-3.481482547, 40.3134419)::geography, 10)
    GROUP BY device_id
)
SELECT device_id
FROM devices_near_A
INTERSECT
SELECT device_id
FROM devices_near_B;

-- Q5 || IoT ||  M -> E
--- Retrieves all devices who were in the same Location as devices uu during the specifoed time period.

SELECT DISTINCT m2.device_id
FROM measurements m1
JOIN measurements m2
    ON ST_DWithin(
        ST_Transform(m1.location, 3857), 
        ST_Transform(m2.location, 3857), 
        100
    )
WHERE m1.device_id = 'urn:ngsi-ld:Device:unibo:a316ef4f55a925842cca39af7280f4d8'
  AND m1.timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
  AND m2.timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
  AND m2.device_id != m1.device_id;

-- Q6 || Spatial ||  E*
--- Find all the polygons that intersect a specific rectangle and store them in the DBMS.

SELECT * FROM
	    (SELECT *
     	 FROM cypher('watering_adf_graph', $$
         MATCH (n)
		 WHERE st_geometrytype(st_geomfromtext(n.location)) = 'ST_Polygon'
         AND st_intersects(st_geomfromtext(n.location), st_geomfromtext('POLYGON ((11.798505 44.234554, 11.800817 44.237283, 11.804886 44.235609, 11.803687 44.234551, 11.804489 44.233483, 11.80238 44.231219, 11.798505 44.234554))'))
         RETURN n
     $$) AS (n agtype)) as s1;

-- Q7 || Time-Series ||  M
--- Selects from a sensor the values that exceed a threshold within a time interval.

SELECT * from measurements
WHERE device_id = 'urn:ngsi-ld:Device:unibo:4706ab32adba82399acb21d45489535c'
AND timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
AND value > 2;

-- Q8 || Time-Series ||  A -> M
--- Downsample the values of sensors and stations from 10 seconds to a 1-hour granularity.

SELECT
    device_id,
	controlledProperty,
    date_trunc('hour', timestamp) AS hourly,
    AVG(value) AS aggregated_value
FROM
    measurements
WHERE value IS NOT NULL
GROUP BY
    device_id,
	controlledProperty,
    hourly
ORDER BY
    device_id,
	controlledProperty,
    hourly;

