-- Q10 || Time-Series ||  A -> M -> E
--- What is the minimum distance between places, where a device with an id from IDs1 and a device with an id from IDs2 have been?

SELECT MIN(st_distance(a.location, b.location)) AS min_distance
FROM measurements a
JOIN measurements b
  ON a.device_id = 'urn:ngsi-ld:AgriRobot:9ea60389-9246-4dda-a083-3e3bcb444131' 
  AND b.device_id = ANY(ARRAY['carob-1', 'Carob @ CSIC', 'carob-123'])
WHERE a.location IS NOT NULL
  AND b.location IS NOT NULL
  AND a.timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
  AND b.timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603);

-- Q11 || Spatio-Temporal || A -> M
--- What are the overall travelled distances of the device with an id from IDs during the periods from QueryPeriods1

WITH ordered_measurements AS (
    SELECT 
        device_id, 
        ST_Transform(location, 3857) as location,
        timestamp,
        LEAD(ST_Transform(location, 3857)) OVER (PARTITION BY device_id ORDER BY timestamp) AS next_location
    FROM measurements
    WHERE device_id = ANY(ARRAY['urn:ngsi-ld:AgriRobot:9ea60389-9246-4dda-a083-3e3bcb444131'])  
    AND timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
)
SELECT device_id, SUM(ST_Distance(location, next_location)) AS total_distance
FROM ordered_measurements
WHERE next_location IS NOT NULL
GROUP BY device_id;

-- Q12 || DT || E* -> A* -> M
--- Return all the devices in each farm that measure soil moisture and their average value from [ta, tb[

SELECT DISTINCT device -> 'properties' ->> 'name' AS device_name, 
       parcel -> 'properties' ->> 'name' AS parcel_name, 
       farm -> 'properties' ->> 'name' AS farm_name,
       meas.average_soilmoisture AS average_soilmoisture
FROM (
    SELECT *
    FROM cypher('watering_adf_graph', $$
        MATCH (device)-[*1..5]-(parcel:AgriParcel)-[*1..10]-(farm:AgriFarm)
        WHERE 'soilMoisture' in device.controlledProperty
        RETURN device, parcel, farm
    $$) AS (device JSON, parcel JSON, farm JSON)
) AS devices_and_farms
JOIN (
    SELECT device_id, AVG(value) AS average_soilmoisture
    FROM measurements
    WHERE timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
    GROUP BY device_id
) as measurements
ON devices_and_farm.device -> 'properties' ->> 'id' = measurement.device_id
ORDER BY farm_name, parcel_name, device_name;

-- Q13 || DT || E -> A* -> M
--- All entities that took some measurements for each farm

SELECT DISTINCT
    farm -> 'properties' ->> 'name' AS farm_name,
    m.device_id
FROM measurements m
JOIN (
    SELECT n AS farm
    FROM cypher('watering_adf_graph', $$
        MATCH (n)
        WHERE n.type = 'AgriFarm'
        RETURN n
    $$) AS (n JSON)
) AS farms
ON ST_Within(m.location, ST_SetSRID(ST_GeomFromText(farms.farm -> 'properties' ->> 'location'), 4326));

-- Q14 || DT || E* -> A* -> M
-- Which entities performing measurements performed a measurements within the period [ta, tb[

SELECT DISTINCT
    devices_in_farm.farm -> 'properties' ->> 'name' AS farm_name,
	devices_in_farm.device -> 'properties' ->> 'name' as device_name
FROM 
    (SELECT *
    FROM cypher('watering_adf_graph', $$
        MATCH (device)-[*1..]-(farm:AgriFarm)
        RETURN farm, device
    $$) AS (farm JSON, device JSON)
) AS devices_in_farm
WHERE devices_in_farm.device -> 'properties' ->> 'id' in (SELECT DISTINCT device_id from measurements WHERE timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603));

-- Q15 || DT || E* -> A* -> M
--- Average hourly soil moisture for each parcel in all farm in [ta, tb]

SELECT
    moisture_in_farm.farm -> 'properties' ->> 'name' AS farm_name,
	moisture_in_farm.parcel -> 'properties' ->> 'name' AS parcel_name,
	moisture_in_farm.device -> 'properties' ->> 'name' as device_name,
	avg(value) as avg_value,
	date_trunc('hour', timestamp) AS hourly
FROM measurements m
JOIN
    (SELECT *
    FROM cypher('watering_adf_graph', $$
        MATCH (device)-[*1..5]-(parcel:AgriParcel)-[]-(farm:AgriFarm)
		WHERE 'soilMoisture' in device.controlledProperty
        RETURN farm, parcel, device
    $$) AS (farm JSON, parcel JSON, device JSON)
) AS moisture_in_farm
ON moisture_in_farm.device -> 'properties' ->> 'id' = m.device_id 
WHERE m.timestamp BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)
GROUP BY farm_name, parcel_name, device_name, hourly
ORDER BY farm_name, parcel_name, device_name, hourly;

-- Q16 || DT | E* -> A -> M
--- Average speed by each robot in each farm

SELECT
    farm -> 'properties' ->> 'name' AS farm_name,
    device -> 'properties' ->> 'name' AS device_name,
    date_trunc('hour', timestamp) AS hourly,
	AVG(m.value) AS avg_speed
FROM measurements m
JOIN (
    SELECT DISTINCT ON (farm::TEXT, device::TEXT) farm, device
    FROM cypher('watering_adf_graph', $$
        MATCH (device:AgriRobot)-[]-(farm:AgriFarm)
		WHERE 'battery' IN device.serviceProvided
        RETURN farm, device
    $$) AS (farm JSON, device JSON)
) AS farm_parcel_device
ON st_within(ST_SetSRID(st_geomfromtext(farm_parcel_device.device -> 'properties' ->> 'location'), 4326), m.location)
WHERE m.controlledProperty = 'battery'
GROUP BY farm_name, device_name, hourly
ORDER BY farm_name, device_name, hourly;

-- Q17 || DT || M -> E-> A 
--- Which devices measured temperature in a farm during the period [ta, tb] 

WITH farm_locations AS (
    SELECT DISTINCT ON (farm -> 'properties' ->> 'location') 
           farm -> 'properties' ->> 'location' AS location_wkt
    FROM cypher('watering_adf_graph', $$
        MATCH (farm:AgriFarm)
        WHERE farm.name CONTAINS 'FABBRICHE'
        RETURN farm
    $$) AS (farm JSON)
)
SELECT DISTINCT device_id
FROM measurements m
JOIN farm_locations f
ON st_within(m.location, ST_SetSRID(st_geomfromtext(f.location_wkt), 4326))
WHERE controlledProperty = 'temperature'
BETWEEN to_timestamp(1720940203) AND  to_timestamp(1721890603)

-- Q18 || DT || E*
--- Historical organization of a farm (parcels through time)

-- Q19 || DT || A* -> M -> E
--- Given a set of agents, which environment did they made measurements?

WITH devices AS (
    SELECT device -> 'properties' ->> 'id' AS device_id
    FROM cypher('watering_adf_graph', $$
        MATCH (device:Device)
        RETURN device
    $$) AS (device JSON)
)
SELECT DISTINCT 
    m.device_id, 
    environments.environment -> 'properties' ->> 'name'
FROM measurements m
JOIN (
    SELECT environment
    FROM cypher('watering_adf_graph', $$
        MATCH (environment)
        WHERE environment.location CONTAINS 'POLYGON'  
        RETURN environment
    $$) AS (environment JSON)
) AS environments
ON st_within(m.location, st_geomfromtext(environments.environment -> 'properties' ->> 'location'))
WHERE m.device_id IN (SELECT device_id FROM devices)